<?php $editing=$editCategory??[];$categoryByLocale=$categoryByLocale??[]; ?>
<section class="panel"><div class="panel-head"><div><span class="panel-kicker">التصنيفات والترجمة</span><h2><?=$editing?'تعديل التصنيف':'إضافة تصنيف'?></h2></div><?php if($editing):?><a class="btn btn-ghost" href="/admin/categories">تصنيف جديد</a><?php endif;?></div>
<form method="post" action="/admin/categories/save" class="form-stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($editing['id']??0)?>"><div class="form-grid two"><label>الترتيب<input type="number" name="sort_order" value="<?=e($editing['sort_order']??0)?>"></label><label class="check"><input type="checkbox" name="active" <?=($editing['active']??1)?'checked':''?>> مفعّل</label></div>
<div class="translation-fields"><?php foreach(enabled_locales() as $locale=>$language):$translation=$categoryByLocale[$locale]??[];?><fieldset><legend><?=e(language_flag($locale).' '.language_name($locale))?></legend><label>الاسم<input name="name[<?=$locale?>]" value="<?=e($translation['name']??'')?>"></label><label>الرابط<input name="slug[<?=$locale?>]" value="<?=e($translation['slug']??'')?>"></label><label>الوصف<textarea name="description[<?=$locale?>]"><?=e($translation['description']??'')?></textarea></label><label>عنوان SEO<input name="seo_title[<?=$locale?>]" value="<?=e($translation['seo_title']??'')?>"></label><label>وصف SEO<textarea name="seo_description[<?=$locale?>]" rows="2"><?=e($translation['seo_description']??'')?></textarea></label><label>الحالة<select name="translation_status[<?=$locale?>]"><option value="draft" <?=($translation['status']??'draft')==='draft'?'selected':''?>>مسودة</option><option value="review" <?=($translation['status']??'')==='review'?'selected':''?>>تحتاج مراجعة</option><option value="published" <?=($translation['status']??'')==='published'?'selected':''?>>منشورة</option></select></label></fieldset><?php endforeach;?></div><button class="btn btn-primary">حفظ التصنيف وترجماته</button></form></section>

<section class="panel"><div class="panel-head"><h2>التصنيفات الحالية</h2><span><?=count($categories)?> تصنيف</span></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>الاسم الأساسي</th><th>الحالة</th><th>الترتيب</th><th></th></tr></thead><tbody><?php foreach($categories as $category):?><tr><td><?=$category['id']?></td><td><?=e($category['ar_name'])?></td><td><?=$category['active']?'مفعّل':'معطّل'?></td><td><?=$category['sort_order']?></td><td><a href="/admin/categories?edit=<?=$category['id']?>">تحرير الترجمات</a></td></tr><?php endforeach;?></tbody></table></div></section>

<section class="panel" id="tags"><div class="panel-head"><div><span class="panel-kicker">وسوم متعددة اللغات</span><h2>إضافة وسم وترجماته</h2></div><span><?=count($tags)?> وسم</span></div><form method="post" action="/admin/tags/save" class="form-stack"><?=csrf_field()?><input type="hidden" name="id" value="0"><div class="translation-fields"><?php foreach(enabled_locales() as $locale=>$language):?><fieldset><legend><?=e(language_flag($locale).' '.language_name($locale))?></legend><label>الاسم<input name="name[<?=$locale?>]"></label><label>الرابط<input name="slug[<?=$locale?>]"></label><label>الوصف<textarea name="description[<?=$locale?>]"></textarea></label><label>عنوان SEO<input name="seo_title[<?=$locale?>]"></label><label>وصف SEO<textarea name="seo_description[<?=$locale?>]" rows="2"></textarea></label><label>الحالة<select name="translation_status[<?=$locale?>]"><option value="draft">مسودة</option><option value="review">تحتاج مراجعة</option><option value="published">منشورة</option></select></label></fieldset><?php endforeach;?></div><button class="btn btn-primary">حفظ الوسم</button></form><?php if($tags):?><div class="table-wrap"><table><thead><tr><th>الوسم</th><th>الترجمات</th></tr></thead><tbody><?php foreach($tags as $tag):?><tr><td><?=e($tag['display_name'])?></td><td><?=$tag['translation_count']?> / <?=count(enabled_locales())?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
